const raw = $input.first().json;
function fromToString(f) {
  if (typeof f === 'string') return f;
  if (Array.isArray(f)) return f.map(x => (x && (x.address || x.name)) || '').filter(Boolean).join(', ');
  if (f && typeof f === 'object') return f.address || f.name || JSON.stringify(f);
  return String(f || '');
}
function senderEmail(f) {
  const s = fromToString(f);
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim();
}
const body = String(raw.text || raw.html || raw.snippet || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);
return [{ json: {
  coi_id: 'COI-' + (raw.messageId || raw.id || Date.now().toString(36).toUpperCase()).replace(/[^A-Za-z0-9]/g, ''),
  sender_email: senderEmail(raw.from),
  subject: raw.Subject || raw.subject || '',
  email_body: body,
  received_at: new Date().toISOString(),
}}];

