const raw = $input.first().json;
let parsed;
try {
  let text = String(raw.output || '');
  text = text.replace(/```json\s*/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { parse_ok: false, error: String(e), snippet: String(raw.output || '').slice(0, 500) } }];
}
const r = parsed || {};
const ok = Boolean(r) && String(r.vendor_name || '').trim() !== '' && String(r.expiration_date || '').trim() !== '';
const n = $('Normalize COI Email').first().json;
return [{ json: {
  parse_ok: ok,
  coi_id: n.coi_id || '',
  received_at: n.received_at || '',
  vendor_name: r.vendor_name || '',
  vendor_email: r.vendor_email || '',
  carrier: r.carrier || '',
  policy_number: r.policy_number || '',
  gl_limit: r.gl_limit || 0,
  auto_limit: r.auto_limit || 0,
  workers_comp: r.workers_comp,
  additional_insured: r.additional_insured,
  effective_date: r.effective_date || '',
  expiration_date: r.expiration_date || '',
  error: ok ? '' : 'missing vendor_name or expiration_date',
}}];

const inp = $input.first().json;
const boolTxt = (v) => (v === true || String(v).toUpperCase() === 'YES' || String(v).toUpperCase() === 'TRUE') ? 'YES' : 'NO';
const wc = (inp.workers_comp === true || String(inp.workers_comp || '').toUpperCase() === 'YES' || String(inp.workers_comp || '').toUpperCase() === 'TRUE');
const ai = (inp.additional_insured === true || String(inp.additional_insured || '').toUpperCase() === 'YES' || String(inp.additional_insured || '').toUpperCase() === 'TRUE');
const expStr = String(inp.expiration_date || '').slice(0, 10);
let daysLeft = null;
if (expStr) {
  const exp = new Date(expStr + 'T23:59:59Z');
  daysLeft = Math.round((exp.getTime() - Date.now()) / 86400000);
}
const gl = Number(inp.gl_limit || 0);
const al = Number(inp.auto_limit || 0);
const missing = [];
if (gl < 1000000) missing.push('general liability 1M');
if (al < 1000000) missing.push('auto liability 1M');
if (!wc) missing.push('workers compensation');
if (!ai) missing.push('additional insured');
if (daysLeft !== null && daysLeft < 0) missing.push('certificate expired');
let stage = 'ok';
if (daysLeft === null) stage = 'incomplete';
else if (daysLeft <= 0) stage = 'expired';
else if (daysLeft <= 10) stage = 'critical';
else if (daysLeft <= 45) stage = 'expiring soon';
if (missing.length > 0 && (stage === 'ok' || stage === 'expiring soon')) stage = 'gap';
const out = {
  vendor_name: inp.vendor_name || '', vendor_email: inp.vendor_email || '',
  carrier: inp.carrier || '', policy_number: inp.policy_number || '',
  gl_limit: gl, auto_limit: al,
  workers_comp: wc, additional_insured: ai,
  workers_comp_txt: boolTxt(wc), additional_insured_txt: boolTxt(ai),
  effective_date: String(inp.effective_date || '').slice(0, 10), expiration_date: expStr,
  status: stage, days_left: daysLeft, missing_items: missing.join(', '),
  coi_id: inp.coi_id || '', received_at: inp.received_at || '',
  checked_at: new Date().toISOString(),
};
return [{ json: out }];

const c = $input.first().json;
const v = c.vendor_name || 'vendor';
const exp = c.expiration_date || 'unknown';
const d = c.days_left;
let subject, body;
if (c.status === 'expired') {
  subject = 'URGENT: Your insurance certificate expired on ' + exp;
  body = 'Hi ' + v + ',\\n\\nYour certificate of insurance expired on ' + exp + '. Please send an updated certificate as soon as possible so we can keep you on the approved vendor list.\\n\\nPolicy: ' + (c.policy_number || 'n/a') + ' | Carrier: ' + (c.carrier || 'n/a');
} else if (c.status === 'critical') {
  subject = 'Your insurance certificate expires in ' + d + ' days';
  body = 'Hi ' + v + ',\\n\\nYour certificate of insurance expires on ' + exp + ' (in ' + d + ' days). Please send a renewed certificate before the expiry date to stay compliant.\\n\\nPolicy: ' + (c.policy_number || 'n/a') + ' | Carrier: ' + (c.carrier || 'n/a');
} else if (c.status === 'expiring soon') {
  subject = 'Reminder: insurance certificate expiring on ' + exp;
  body = 'Hi ' + v + ',\\n\\nA friendly reminder that your certificate of insurance expires on ' + exp + ' (in ' + d + ' days). Please arrange a renewal.\\n\\nPolicy: ' + (c.policy_number || 'n/a') + ' | Carrier: ' + (c.carrier || 'n/a');
} else {
  subject = 'Action needed: insurance certificate missing required coverage';
  body = 'Hi ' + v + ',\\n\\nYour certificate of insurance is missing required coverage: ' + (c.missing_items || 'required items') + '. Please send an updated certificate that covers these items.\\n\\nPolicy: ' + (c.policy_number || 'n/a') + ' | Carrier: ' + (c.carrier || 'n/a');
}
return [{ json: Object.assign({}, c, { mail_subject: subject, mail_body: body, is_critical: (c.status === 'expired' || c.status === 'critical') }) }];

const rows = $input.all().map(i => i.json);
const out = [];
for (const r of rows) {
  const expStr = String(r.expiration_date || '').slice(0, 10);
  if (!expStr) continue;
  const exp = new Date(expStr + 'T23:59:59Z');
  const days = Math.round((exp.getTime() - Date.now()) / 86400000);
  if (days > 45) continue;
  const stage = days <= 0 ? 'expired' : (days <= 10 ? 'critical' : 'soon');
  const name = r.vendor_name || 'vendor';
  const email = r.vendor_email || '';
  let subject, body;
  if (stage === 'expired') {
    subject = 'URGENT: insurance certificate expired on ' + expStr;
    body = 'Hi ' + name + ',\\n\\nYour certificate of insurance expired on ' + expStr + '. Please send an updated certificate immediately.';
  } else {
    subject = 'Reminder: insurance certificate expires in ' + days + ' days';
    body = 'Hi ' + name + ',\\n\\nThis is a reminder that your certificate of insurance expires on ' + expStr + ' (in ' + days + ' days). Please renew it before the expiry date.';
  }
  out.push({ vendor_name: name, vendor_email: email, stage: stage, days_left: days, reminder_subject: subject, reminder_body: body });
}
return [{ json: { items: out, needs_action_count: out.length } }];

const rows = $input.all().map(i => i.json);
let total = rows.length, compliant = 0, gap = 0, expired = 0, expiring = 0;
const expiringList = [];
for (const r of rows) {
  const status = String(r.status || 'ok');
  const expStr = String(r.expiration_date || '').slice(0, 10);
  let days = null;
  if (expStr) {
    const exp = new Date(expStr + 'T23:59:59Z');
    days = Math.round((exp.getTime() - Date.now()) / 86400000);
  }
  if (days !== null && days <= 0) { expired++; }
  else if (days !== null && days <= 30) { expiring++; expiringList.push((r.vendor_name || '?') + ' (' + expStr + ')'); }
  if (status === 'ok' || status === 'compliant') compliant++;
  else if (status !== '') gap++;
}
return [{ json: {
  total: total, compliant: compliant, gap: gap, expired: expired, expiring: expiring,
  expiring_names: expiringList.join(', ') || 'none',
  summary: total + ' vendors on file, ' + compliant + ' compliant, ' + gap + ' with gaps, ' + expired + ' expired, ' + expiring + ' expiring within 30 days',
}}];

const inp = $input.first().json;
let digest = String(inp.output || '');
digest = digest.replace(/```\w*\s*/g, '').trim();
const stats = $('Compute Digest Stats').first().json;
return [{ json: Object.assign({}, stats, { digest: digest }) }];
